-- Import Hisnul Mouslim cours 1 (révision): 50 questions "Introduction et importance du dhikr" depuis hisn1.json.
-- tenant Abou Abdelwahab (qawaid.abouabdelwahab.com). Remplace le contenu de cours 1.
-- À exécuter une seule fois.

do $$ declare t uuid:='6badf254-27a3-4f69-98e3-e67caa917371'; c uuid;
begin
  select id into c from quiz_courses where tenant_id=t and subject='Hisnul Mouslim' and number=1;
  if c is null then
      values (t,'Hisnul Mouslim',1,'Introduction et importance du dhikr',1) returning id into c;
  else
    update quiz_courses set title='Introduction et importance du dhikr' where id=c;
    delete from quiz_questions where course_id=c;
  end if;
end $$;
